ALTER TABLE users ADD COLUMN mail text NOT NULL DEFAULT '', ADD COLUMN remark text NOT NULL DEFAULT '', ADD COLUMN version bigint NOT NULL DEFAULT 1, ADD COLUMN deleted_at timestamptz, ADD COLUMN force_mfa boolean NOT NULL DEFAULT false;
ALTER TABLE auth_sessions ADD COLUMN phase text NOT NULL DEFAULT 'authenticated' CHECK(phase IN ('authenticated','mfa_pending','mfa_enroll')), ADD COLUMN mfa_attempts integer NOT NULL DEFAULT 0;
CREATE TABLE departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, parent_id uuid REFERENCES departments(id), weight integer NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX departments_name ON departments(parent_id,name) NULLS NOT DISTINCT;
CREATE TABLE user_departments(user_id uuid NOT NULL REFERENCES users(id), department_id uuid NOT NULL REFERENCES departments(id), PRIMARY KEY(user_id,department_id));
CREATE TABLE permissions(action text PRIMARY KEY, menu_key text NOT NULL, label text NOT NULL);
INSERT INTO permissions VALUES ('user.read','user','用户查看'),('department.read','department','部门查看'),('role.read','role','角色查看'),('lock.read','login-locked','登录锁定查看'),('audit.read','audit','基础审计查看'),('settings.read','settings','基础配置查看');
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles(user_id uuid NOT NULL REFERENCES users(id),role_id uuid NOT NULL REFERENCES roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions(role_id uuid NOT NULL REFERENCES roles(id),action text NOT NULL REFERENCES permissions(action),PRIMARY KEY(role_id,action));
CREATE TABLE login_locks(username text PRIMARY KEY,failures integer NOT NULL DEFAULT 0,locked_until timestamptz,last_failed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_challenges(id text PRIMARY KEY,purpose text NOT NULL,binding_hash text NOT NULL,answer integer NOT NULL,verified boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE INDEX auth_challenges_expiry ON auth_challenges(expires_at);
CREATE TABLE mfa_factors(user_id uuid PRIMARY KEY REFERENCES users(id),secret_cipher bytea, pending_cipher bytea,pending_expires_at timestamptz,last_step bigint NOT NULL DEFAULT -1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mfa_recovery_codes(user_id uuid NOT NULL REFERENCES users(id),code_hash text NOT NULL,used_at timestamptz,PRIMARY KEY(user_id,code_hash));
ALTER TABLE operation_logs ADD COLUMN details jsonb NOT NULL DEFAULT '{}';
UPDATE settings SET typed_value='true',revision=revision+1 WHERE key='login-captcha-enabled';
ALTER TABLE instance_state ADD COLUMN mfa_key_fingerprint text NOT NULL DEFAULT '';
UPDATE instance_state SET schema_version=2;
